import sys
import sqlite3
import json
import re
from datetime import datetime, timezone
from typing import Dict, Any, List, Optional

def evaluate_condition(condition_text: str, user: str, resource: str, ctx: Dict[str, Any]) -> bool:
    def parse_expression(expr: str) -> Any:
        tokens = re.findall(r'(\w+|==|!=|<=|>=|<|>|and|or|not|\(|\)|\'[^\']*\'|\"[^\"]*\"|\d+|true|false|[^\w\s\'"<>!]=)', expr)
        tokens = [t.strip() for t in tokens if t.strip()]
        tokens = [t.lower() for t in tokens]

        def parse_atom():
            if tokens and tokens[0] == 'true':
                tokens.pop(0)
                return True
            elif tokens and tokens[0] == 'false':
                tokens.pop(0)
                return False
            elif tokens and tokens[0].isdigit():
                tokens.pop(0)
                return int(tokens[0])
            elif tokens and tokens[0].startswith('"') and tokens[0].endswith('"'):
                tokens.pop(0)
                return tokens[0][1:-1]
            elif tokens and tokens[0].startswith("'") and tokens[0].endswith("'"):
                tokens.pop(0)
                return tokens[0][1:-1]
            elif tokens and tokens[0] == 'user':
                tokens.pop(0)
                return user
            elif tokens and tokens[0] == 'resource':
                tokens.pop(0)
                return resource
            elif tokens and tokens[0] == 'ctx':
                tokens.pop(0)
                return ctx
            else:
                raise ValueError(f"Unexpected token: {tokens[0]}")

        def parse_primary():
            if tokens and tokens[0] == '(':
                tokens.pop(0)
                expr = parse_expression()
                if tokens and tokens[0] == ')':
                    tokens.pop(0)
                else:
                    raise ValueError("Missing closing parenthesis")
                return expr
            else:
                return parse_atom()

        def parse_factor():
            expr = parse_primary()
            while tokens and tokens[0] == '[':
                tokens.pop(0)
                key = parse_atom()
                tokens.pop(0)  # ')'
                if isinstance(expr, dict):
                    expr = expr.get(key, None)
                else:
                    raise ValueError("Cannot use subscript on non-dict")
            return expr

        def parse_term():
            expr = parse_factor()
            while tokens and tokens[0] in ('+', '-'):
                op = tokens.pop(0)
                next_expr = parse_factor()
                if op == '+':
                    expr += next_expr
                else:
                    expr -= next_expr
            return expr

        def parse_expr():
            expr = parse_term()
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.pop(0)
                next_expr = parse_term()
                if op == '*':
                    expr *= next_expr
                else:
                    expr /= next_expr
            return expr

        def parse_comparison():
            left = parse_expr()
            op = tokens.pop(0)
            right = parse_expr()
            if op == '==':
                return left == right
            elif op == '!=':
                return left != right
            elif op == '<':
                return left < right
            elif op == '<=':
                return left <= right
            elif op == '>':
                return left > right
            elif op == '>=':
                return left >= right
            else:
                raise ValueError(f"Unexpected operator: {op}")

        def parse_logical():
            left = parse_comparison()
            op = tokens.pop(0)
            right = parse_comparison()
            if op == 'and':
                return left and right
            elif op == 'or':
                return left or right
            else:
                raise ValueError(f"Unexpected operator: {op}")

        def parse_not():
            if tokens and tokens[0] == 'not':
                tokens.pop(0)
                return not parse_logical()
            else:
                return parse_logical()

        result = parse_not()
        if tokens:
            raise ValueError(f"Unexpected token at end: {tokens[0]}")
        return result

    try:
        return parse_expression(condition_text)
    except ValueError as e:
        raise ValueError(f"Invalid condition: {e}")

