import sys
import sqlite3
import json
from sqlite3 import Error

def create_connection(db_file):
    conn = None
    try:
        conn = sqlite3.connect(db_file)
        return conn
    except Error as e:
        print(f"Error connecting to database: {e}")
        sys.exit(1)

def execute_query(conn, query):
    cursor = conn.cursor()
    try:
        cursor.execute(query)
        return cursor.fetchall()
    except Error as e:
        print(f"Error executing query: {e}")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python access_check.py <database_file>")
        sys.exit(1)

    db_file = sys.argv[1]
    conn = create_connection(db_file)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        token, resource, context_json_str = line.split('\t', 2)
        try:
            context = json.loads(context_json_str)
        except json.JSONDecodeError:
            print("DENY condition_false")
            continue

        # Get token user
        token_query = "SELECT user FROM tokens WHERE token = ?"
        token_result = execute_query(conn, token_query, (token,))
        if not token_result:
            print("DENY no_token")
            continue

        token_user = token_result[0][0]

        # Get rules for this user and resource
        rules_query = "SELECT id FROM rules WHERE user = ? AND resource = ? ORDER BY id ASC"
        rules_result = execute_query(conn, rules_query, (token_user, resource))
        if not rules_result:
            print("DENY no_rule")
            continue

        # Evaluate the lexicographically smallest rule
        rule_id = rules_result[0][0]
        rule_condition = f"user == '{token_user}' and resource == '{resource}' and ctx == {context}"
        try:
            if eval(rule_condition):
                print(f"ALLOW {rule_id}")
            else:
                print("DENY condition_false")
        except:
            print("DENY condition_false")

    conn.close()

if __name__ == "__main__":
    main()
